// snippets.ts: the first-run MCP client configs (S25 §3.3), built at compile time from S14/S15's
// golden files in examples/clients (generated by `deedglass mcp snippet`), so the Console and the
// CLI print the same bytes. fill() swaps in the server, the new agent's key, the connector and the
// deedglass binary; test/snippets.test.ts renders each with the goldens' own inputs and compares.

import claudeCode from '../../../examples/clients/http-claude-code.sh?raw';
import claudeDesktop from '../../../examples/clients/http-claude-desktop.json?raw';
import cursor from '../../../examples/clients/http-cursor.json?raw';

export type Client = 'claude-code' | 'cursor' | 'claude-desktop';
export const CLIENTS: readonly Client[] = ['claude-code', 'cursor', 'claude-desktop'];

/** The values the goldens were generated with (internal/mcp/snippet). */
export const GOLDEN = { server: 'http://127.0.0.1:8080', apiKey: 'dg_test_REPLACE_ME', connector: 'native', command: '/Users/you/txv/product/bin/deedglass' } as const;

const TEMPLATES: Record<Client, { text: string; lang: string; where: string }> = {
  'claude-code': { text: claudeCode, lang: 'shell', where: 'Run it in a terminal.' },
  cursor: { text: cursor, lang: '.cursor/mcp.json', where: 'Put it in ~/.cursor/mcp.json or .cursor/mcp.json.' },
  'claude-desktop': { text: claudeDesktop, lang: 'claude_desktop_config.json', where: "Claude Desktop runs deedglass mcp serve: its remote connectors can't reach 127.0.0.1. Use the binary's absolute path." },
};

export interface SnippetInput {
  server: string;
  apiKey: string;
  connector?: string;
  command?: string;
}

function replaceAll(s: string, from: string, to: string): string {
  return s.split(from).join(to);
}

/** JSON-string-safe: the values land inside JSON strings and a single-quoted shell word. */
function safe(v: string): string {
  return /^[A-Za-z0-9._:/@+=-]*$/.test(v) ? v : '';
}

export function snippet(client: Client, i: SnippetInput): { text: string; lang: string; where: string } {
  const t = TEMPLATES[client];
  let text = t.text;
  // The command first: its path contains no other placeholder.
  text = replaceAll(text, GOLDEN.command, safe(i.command ?? 'deedglass') || 'deedglass');
  text = replaceAll(text, GOLDEN.apiKey, safe(i.apiKey) || GOLDEN.apiKey);
  text = replaceAll(text, `/mcp/${GOLDEN.connector}`, `/mcp/${safe(i.connector ?? GOLDEN.connector) || GOLDEN.connector}`);
  text = replaceAll(text, `"${GOLDEN.connector}"`, `"${safe(i.connector ?? GOLDEN.connector) || GOLDEN.connector}"`);
  text = replaceAll(text, GOLDEN.server, safe(i.server) || GOLDEN.server);
  return { text, lang: t.lang, where: t.where };
}
